// golden is testdata/mods/golden.json: what Bazarr's own code makes of
// the subtitles of testdata/mods, generated by golden.py.
type golden struct {
	Mods []struct {
		Name     string            `json:"name"`
		File     string            `json:"file"`
		Language string            `json:"language"`
		Mods     []string          `json:"mods"`
		Used     []string          `json:"used"`
		RawCues  []json.RawMessage `json:"cues"`
	} `json:"mods"`
	Languages []struct {
		Name  string `json:"name"`
		Text  string `json:"text"`
		Guess string `json:"guess"`
	} `json:"languages"`
	Files []struct {
		File  string `json:"file"`
		Guess string `json:"guess"`
	} `json:"files"`
	HearingImpaired []struct {
		Name     string `json:"name"`
		Text     string `json:"text"`
		Language string `json:"language"`
		HI       bool   `json:"hi"`
	} `json:"hearing_impaired"`
}

func loadGolden(t *testing.T) golden {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "mods", "golden.json"))
	if err != nil {
		t.Fatal(err)
	}
	var g golden
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatal(err)
	}
	return g
}

func readModsFile(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "mods", name))
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func parseModsFile(t *testing.T, name string) *Subtitle {
	t.Helper()
	s, err := Parse(readModsFile(t, name), strings.TrimPrefix(filepath.Ext(name), "."))
	if err != nil {
		t.Fatal(err)
	}
	return s
}

func TestPortedMods(t *testing.T) {
	portedCases(t, "mods.json", ported{
		facts: map[string]string{"test_apply_mods_remove_hi": "TestApplyModsRemoveHI"},
		skip:  map[string]string{"test_file": "a pytest fixture, not a test"},
	})
}

func TestApplyModsRemoveHI(t *testing.T) {
	s := parseModsFile(t, "subs_for_mods.srt")
	if _, err := s.ApplyMods("en", []string{"remove_HI", "OCR_fixes"}); err != nil {
		t.Fatal(err)
	}
	out, err := Write(s, SRT)
	if err != nil {
		t.Fatal(err)
	}
	if len(out) == 0 {
		t.Errorf("modified content: got = empty, want = content")
	}
}

// goldenCue is a cue as golden.json records it.
type goldenCue struct {
	Start, End int64
	Text       string
}

func TestModsGolden(t *testing.T) {
	for _, sc := range loadGolden(t).Mods {
		t.Run(sc.Name, func(t *testing.T) {
			var want []goldenCue
			for _, raw := range sc.RawCues {
				var c [3]any
				if err := json.Unmarshal(raw, &c); err != nil {
					t.Fatal(err)
				}
				want = append(want, goldenCue{int64(c[0].(float64)), int64(c[1].(float64)), c[2].(string)})
			}
			s := parseModsFile(t, sc.File)
			used, err := s.ApplyMods(sc.Language, sc.Mods)
			if err != nil {
				t.Fatal(err)
			}
			if !slices.Equal(used, sc.Used) {
				t.Errorf("used: got = %q, want = %q", used, sc.Used)
			}
			got := make([]goldenCue, len(s.Cues))
			for i, c := range s.Cues {
				got[i] = goldenCue{c.Start.Milliseconds(), c.End.Milliseconds(), c.Text}
			}
			if len(got) != len(want) {
				t.Errorf("cues: got = %d, want = %d", len(got), len(want))
			}
			// Report the first differences.
			reported := 0
			for i := range min(len(got), len(want)) {
				if got[i] != want[i] && reported < 5 {
					reported++
					t.Errorf("cue %d: got = %d–%d %q, want = %d–%d %q", i+1,
						got[i].Start, got[i].End, got[i].Text, want[i].Start, want[i].End, want[i].Text)
				}
			}
		})
	}
}

func TestDetectLanguageGolden(t *testing.T) {
	g := loadGolden(t)
	check := func(t *testing.T, text, guess, want string) {
		t.Helper()
		if guess == "zh" {
			// Bazarr's guess; Mavio tells the script apart.
			guess = want
		}
		if got := DetectLanguage(text); got != guess {
			t.Errorf("DetectLanguage: got = %q, want = %q", got, guess)
		}
	}
	for _, c := range g.Languages {
		t.Run(c.Name, func(t *testing.T) {
			want := c.Guess
			if strings.HasPrefix(c.Name, "zh-") {
				want = c.Name
			}
			check(t, c.Text, c.Guess, want)
		})
	}
	for _, c := range g.Files {
		t.Run(c.File, func(t *testing.T) { check(t, string(readModsFile(t, c.File)), c.Guess, c.Guess) })
	}
}

func TestDetectHearingImpairedGolden(t *testing.T) {
	for _, c := range loadGolden(t).HearingImpaired {
		t.Run(c.Name, func(t *testing.T) {
			if got := DetectHearingImpaired(c.Text, iso3ToTag(c.Language)); got != c.HI {
				t.Errorf("DetectHearingImpaired: got = %v, want = %v", got, c.HI)
			}
			crlf := strings.ReplaceAll(c.Text, "\n", "\r\n")
			if got := DetectHearingImpaired(crlf, iso3ToTag(c.Language)); got != c.HI {
				t.Errorf("DetectHearingImpaired with CRLF: got = %v, want = %v", got, c.HI)
			}
		})
	}
}

// iso3ToTag maps the alpha-3 codes of golden.json to BCP 47 tags.
func iso3ToTag(code string) string {
	return map[string]string{"eng": "en", "ara": "ar", "fas": "fa", "": ""}[code]
}

func TestDetectHearingImpaired(t *testing.T) {
	tests := []struct {
		name, text, language string
		want                 bool
	}{
		{"brackets", "[DOOR SLAMS]", "en", true},
		{"parentheses", "(laughs) Hi.", "en", true},
		{"parentheses in Persian", "(یادداشت) سلام", "fa", false},
		{"parentheses in Arabic with region", "(ملاحظة) مرحبا", "ar-EG", false},
		{"braces", "{sighs} fine", "en", true},
		{"music", "♪ la la ♪", "en", true},
		{"asterisks", "*whispers*", "", true},
		{"short", "[a]", "en", false},
		{"position tag", `{\an8}Top`, "en", false},
		{"across lines", "[DOOR\nSLAMS]", "en", false},
		{"plain", "Hello there.", "en", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := DetectHearingImpaired(tt.text, tt.language); got != tt.want {
				t.Errorf("DetectHearingImpaired(%q, %q): got = %v, want = %v", tt.text, tt.language, got, tt.want)
			}
		})
	}
}

