func TestDetectLanguage(t *testing.T) {
	tests := []struct {
		name, text, want string
	}{
		{"simplified", "我们今天晚上一起去看电影吧，听说这部电影非常好看。", "zh-Hans"},
		{"traditional", "我們今天晚上一起去看電影吧，聽說這部電影非常好看。", "zh-Hant"},
		{"mostly traditional", "我們今天晚上一起去看電影吧，听說這部電影非常好看。", "zh-Hant"},
		{"shared characters only", "中文中文中文", "zh"},
		{"english", "The quick brown fox jumps over the lazy dog while the children watch.", "en"},
		{"too short", "Hi there", ""},
		{"empty", "", ""},
		{"digits", "1234 5678", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := DetectLanguage(tt.text); got != tt.want {
				t.Errorf("DetectLanguage(%q): got = %q, want = %q", tt.text, got, tt.want)
			}
		})
	}
}

func TestCheckMod(t *testing.T) {
	tests := []struct {
		identifier string
		ok         bool
	}{
		{"common", true},
		{"remove_HI", true},
		{"OCR_fixes", true},
		{"remove_tags", true},
		{"reverse_rtl", true},
		{"fix_uppercase", true},
		{"emoji", true},
		{"color(name=yellow)", true},
		{"color(name=pink)", true},
		{"change_FPS(from=23.976,to=25)", true},
		{"shift_offset(h=0,m=0,s=-1,ms=500)", true},
		{"two_point_fit(rh=0,rm=0,rs=1,rms=0,oh=0,om=0,os=2,oms=0,from=23.976,to=24)", true},
		{"unknown", false},
		{"", false},
		{"shift_offset(s=one)", false},
		{"shift_offset(s)", false},
		{"shift_offset(s=1", false},
		{"change_FPS(from=0,to=25)", false},
		{"change_FPS(from=25)", false},
		{"two_point_fit(from=25,to=24,rs=x)", false},
	}
	for _, tt := range tests {
		t.Run(tt.identifier, func(t *testing.T) {
			err := CheckMod(tt.identifier)
			if (err == nil) != tt.ok {
				t.Errorf("CheckMod(%q): got = %v, want ok = %v", tt.identifier, err, tt.ok)
			}
			if err != nil && !errors.Is(err, ErrInvalidMod) {
				t.Errorf("CheckMod(%q): got = %v, want = ErrInvalidMod", tt.identifier, err)
			}
		})
	}
}

func TestApplyModsInvalid(t *testing.T) {
	s := &Subtitle{Cues: []Cue{{Index: 1, Start: time.Second, End: 2 * time.Second, Text: "hello  world"}}}
	if _, err := s.ApplyMods("en", []string{"common", "bogus"}); !errors.Is(err, ErrInvalidMod) {
		t.Fatalf("ApplyMods: got = %v, want = ErrInvalidMod", err)
	}
	if s.Cues[0].Text != "hello  world" {
		t.Errorf("text: got = %q, want = unchanged", s.Cues[0].Text)
	}
}

func TestModNames(t *testing.T) {
	for _, name := range ModNames() {
		if err := CheckMod(name); err != nil && !strings.Contains(name, "(") {
			// Mods with required arguments fail without them.
			if _, ok := modSpecs[name]; !ok || modSpecs[name].check == nil {
				t.Errorf("CheckMod(%q): got = %v, want = nil", name, err)
			}
		}
	}
	if got := len(ModColors()); got != 16 {
		t.Errorf("ModColors: got = %d colors, want = 16", got)
	}
}

// modCase is a cue's text before and after mods.
type modCase struct {
	name, language string
	mods           []string
	text, want     string
	// dropped is set when the cue is to be removed.
	dropped bool
}

func runModCases(t *testing.T, tests []modCase) {
	t.Helper()
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// A second cue keeps the subtitle from losing every cue, which
			// Subzero treats as nothing to change.
			s := &Subtitle{Cues: []Cue{
				{Index: 1, Start: time.Second, End: 2 * time.Second, Text: tt.text},
				{Index: 2, Start: 3 * time.Second, End: 4 * time.Second, Text: "Keep."},
			}}
			if _, err := s.ApplyMods(tt.language, tt.mods); err != nil {
				t.Fatal(err)
			}
			if tt.dropped {
				if len(s.Cues) != 1 {
					t.Errorf("%q: got = %q, want = dropped", tt.text, s.Cues[0].Text)
				}
				return
			}
			if len(s.Cues) != 2 {
				t.Fatalf("%q: got = dropped, want = %q", tt.text, tt.want)
			}
			if s.Cues[0].Text != tt.want {
				t.Errorf("%q: got = %q, want = %q", tt.text, s.Cues[0].Text, tt.want)
			}
		})
	}
}

func TestModCommon(t *testing.T) {
	common := []string{"common"}
	runModCases(t, []modCase{
		{name: "hyphens", language: "en", mods: common, text: "‐ Yes.", want: "- Yes."},
		{name: "multidash", language: "en", mods: common, text: "Wait-- what?", want: "Wait— what?"},
		{name: "non-word only", language: "en", mods: common, text: "Hi.\n- - -", want: "Hi."},
		{name: "leading crocodiles", language: "en", mods: common, text: ">> Hello.", want: "Hello."},
		{name: "music symbols", language: "en", mods: common, text: "# Singing along #", want: "♪ Singing along ♪"},
		{name: "double apostrophe", language: "en", mods: common, text: "''Quote''", want: `"Quote"`},
		{name: "double as single", language: "en", mods: common, text: `Don"t go.`, want: "Don't go."},
		{name: "single quotes", language: "en", mods: common, text: "It’s fine.", want: "It's fine."},
		{name: "leading ellipsis", language: "en", mods: common, text: "...and then.", want: "and then."},
		{name: "downloaded from", language: "en", mods: common, text: "Subtitles downloaded from example.org", dropped: true},
		{name: "ellipsis space", language: "en", mods: common, text: "Wait...what?", want: "Wait... what?"},
		{name: "multiple spaces", language: "en", mods: common, text: "Two   spaces.", want: "Two spaces."},
		{name: "dots", language: "en", mods: common, text: "Wait.....", want: "Wait..."},
		{name: "dash space", language: "en", mods: common, text: "-Yes.\n-No.", want: "- Yes.\n- No."},
		{name: "uppercase I in word", language: "en", mods: common, text: "HeIlo.", want: "Hello."},
		{name: "spaces in numbers", language: "en", mods: common, text: "It costs 1 000 dollars.", want: "It costs 1000 dollars."},
		{name: "uppercase after dot", language: "en", mods: common, text: "Hello there. how are you?", want: "Hello there. How are you?"},
		{name: "double interpunct", language: "en", mods: common, text: "What?!", want: "What?"},
		{name: "double interpunct in Spanish", language: "es", mods: common, text: "¿Qué?!", want: "¿Qué?!"},
		{name: "double interpunct in Spanish of Spain", language: "es-ES", mods: common, text: "¿Qué?!", want: "¿Qué?"},
		{name: "space before punctuation", language: "en", mods: common, text: "Hello , world !", want: "Hello, world!"},
		{name: "space after punctuation", language: "en", mods: common, text: "Hello,world.", want: "Hello, world."},
		{name: "domain kept", language: "en", mods: common, text: "Visit google.com today.", want: "Visit google.com today."},
		{name: "lowercase i in English", language: "en", mods: common, text: "Yes, i know.", want: "Yes, I know."},
		{name: "lowercase i in English of the US", language: "en-US", mods: common, text: "Yes, i know.", want: "Yes, i know."},
		{name: "lowercase i in French", language: "fr", mods: common, text: "Oui, i know.", want: "Oui, i know."},
		{name: "empty tag", language: "en", mods: common, text: `{\i1} - {\i0}Hi.`, want: "Hi."},
	})
}

func TestModHearingImpaired(t *testing.T) {
	hi := []string{"remove_HI"}
	runModCases(t, []modCase{
		{name: "full brackets", language: "en", mods: hi, text: "[DOOR SLAMS]", dropped: true},
		{name: "full brackets on two lines", language: "en", mods: hi, text: "(sighing\nloudly)", dropped: true},
		{name: "speaker in caps", language: "en", mods: hi, text: "JOHN: Hello.", want: "Hello."},
		{name: "speaker", language: "en", mods: hi, text: "John: Hello.", want: "Hello."},
		{name: "sentence with colon kept", language: "en", mods: hi, text: "He said this: Hello.", want: "He said this: Hello."},
		{name: "brackets in line", language: "en", mods: hi, text: "[sighs] Fine.", want: "Fine."},
		{name: "all caps cue", language: "en", mods: hi, text: "Fine.\nLAUGHTER", want: "Fine."},
		{name: "all caps kept", language: "en", mods: hi, text: "Fine.\nNASA", want: "Fine.\nNASA"},
		{name: "woman", language: "en", mods: hi, text: "WOMAN: Hello.", want: "Hello."},
		{name: "starting upper then sentence", language: "en", mods: hi, text: "LOUD NOISE This is it.", want: "This is it."},
		{name: "music cue", language: "en", mods: hi, text: "♪ Singing along ♪", dropped: true},
		{name: "music symbols only", language: "en", mods: hi, text: "♪ ♪", dropped: true},
		{name: "Japanese parentheses", language: "ja", mods: hi, text: "（笑い）こんにちは", want: "こんにちは"},
		{name: "Japanese parentheses in English", language: "en", mods: hi, text: "Hi (there) you", want: "Hi (there) you"},
		{name: "dash only left", language: "en", mods: hi, text: "- [sighs]\n- Fine.", want: "- Fine."},
		{name: "tags around", language: "en", mods: hi, text: `{\i1}[sighs] Fine.{\i0}`, want: `{\i1}Fine.{\i0}`},
	})
}

