func TestFixUppercase(t *testing.T) {
	tests := []struct{ text, want string }{
		{"HELLO THERE. HOW ARE YOU?", "Hello there. How are you?"},
		{"- YES!\n- NO.", "- Yes!\n- No."},
		{"♪ LA LA ♪", "♪ La la ♪"},
	}
	for _, tt := range tests {
		if got := fixUppercase(tt.text); got != tt.want {
			t.Errorf("fixUppercase(%q): got = %q, want = %q", tt.text, got, tt.want)
		}
	}
}

func TestModTiming(t *testing.T) {
	tests := []struct {
		name       string
		mods       []string
		used       []string
		start, end time.Duration
	}{
		{
			"shift",
			[]string{"shift_offset(s=1,ms=500)"},
			[]string{"shift_offset(s=1,ms=500)"},
			2500 * time.Millisecond, 4500 * time.Millisecond,
		},
		{
			"shifts merged",
			[]string{"shift_offset(s=1)", "common", "shift_offset(s=-2,ms=250)"},
			[]string{"shift_offset(s=-1,ms=250)", "common"},
			250 * time.Millisecond, 2250 * time.Millisecond,
		},
		{
			"shifts cancelled",
			[]string{"shift_offset(s=1)", "shift_offset(s=-1)"},
			nil,
			time.Second, 3 * time.Second,
		},
		{
			"frame rate",
			[]string{"change_FPS(from=25,to=50)"},
			[]string{"change_FPS(from=25,to=50)"},
			500 * time.Millisecond, 1500 * time.Millisecond,
		},
		{
			"two point fit",
			[]string{"two_point_fit(rs=1,os=2,from=25,to=50)"},
			[]string{"two_point_fit(rs=1,os=2,from=25,to=50)"},
			2 * time.Second, 3 * time.Second,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			s := &Subtitle{Cues: []Cue{{Index: 1, Start: time.Second, End: 3 * time.Second, Text: "Hello."}}}
			used, err := s.ApplyMods("en", tt.mods)
			if err != nil {
				t.Fatal(err)
			}
			if !slices.Equal(used, tt.used) {
				t.Errorf("used: got = %q, want = %q", used, tt.used)
			}
			if c := s.Cues[0]; c.Start != tt.start || c.End != tt.end {
				t.Errorf("timing: got = %v–%v, want = %v–%v", c.Start, c.End, tt.start, tt.end)
			}
		})
	}
}

func TestPrepareModsExclusive(t *testing.T) {
	s := &Subtitle{Cues: []Cue{{Index: 1, Start: time.Second, End: 2 * time.Second, Text: "Hi"}}}
	used, err := s.ApplyMods("en", []string{"color(name=red)", "common", "color(name=blue)"})
	if err != nil {
		t.Fatal(err)
	}
	if want := []string{"color(name=red)", "common", "color(name=blue)"}; !slices.Equal(used, want) {
		t.Errorf("used: got = %q, want = %q", used, want)
	}
	if want := `<font color="#0000FF">Hi</font>`; s.Cues[0].Text != want {
		t.Errorf("text: got = %q, want = %q", s.Cues[0].Text, want)
	}
}
